package main

import (
	"strings"
	"unicode"
)

// goKeywords is the list of Go reserved words.
var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true,
	"continue": true, "default": true, "defer": true, "else": true,
	"fallthrough": true, "for": true, "func": true, "go": true,
	"goto": true, "if": true, "import": true, "interface": true,
	"map": true, "package": true, "range": true, "return": true,
	"select": true, "struct": true, "switch": true, "type": true,
	"var": true,
}

// goTypes is the list of Go primitive type names which must not be camelized.
var goTypes = map[string]bool{
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint16": true, "uint32": true, "float32": true, "float64": true,
	"bool": true, "byte": true, "string": true,
}

// camelize capitalizes the first letter of each word and removes invalid
// characters.
func camelize(s string) string {
	if s == "" {
		return "EmptyString"
	}
	if goTypes[s] {
		return s
	}

	var out strings.Builder
	first := true
	for _, c := range s {
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			// removed
		case unicode.IsLetter(c):
			if first {
				out.WriteRune(unicode.ToUpper(c))
				first = false
			} else {
				out.WriteRune(c)
			}
		case unicode.IsDigit(c):
			out.WriteRune(c)
			first = false
		case c == '_':
			out.WriteRune(c)
			first = false
		case c == '-', c == '.':
			out.WriteByte('_')
			first = false
		case c == '+':
			out.WriteString("Plus")
			first = false
		case c == '@':
			out.WriteString("At")
			first = false
		}
	}
	res := out.String()
	if res == "" {
		return "EmptyString"
	}
	return res
}

// checkName appends an underscore to Go reserved words.
func checkName(s string) string {
	if goKeywords[s] {
		return s + "_"
	}
	return s
}

// typeName returns the Go type name used in declarations.
func typeName(s string) string {
	return checkName(camelize(s))
}

// refName returns the Go type name used when referencing a declared type.
func refName(s string) string {
	return camelize(s)
}

// fieldName returns the Go field name for an element reference field.
func fieldName(s string) string {
	n := checkName(camelize(s))
	if n == "string" {
		return "A" + n
	}
	return n
}

// elemName returns the Go field name for a local type field.
func elemName(s string) string {
	return camelize(s)
}

// localName strips the namespace prefix of a qualified name.
func localName(s string) string {
	parts := strings.Split(s, ":")
	if len(parts) == 2 {
		return parts[1]
	}
	return parts[0]
}

func comment(s string) string {
	if strings.TrimSpace(s) == "" {
		return ""
	}
	var out strings.Builder
	for i, l := range strings.Split(s, "\n") {
		if i > 0 {
			out.WriteString("\n")
		}
		out.WriteString("// ")
		out.WriteString(strings.TrimLeft(l, " \t"))
	}
	return out.String()
}
GOEOF
echo ok"}

