package main

// WSDL structures as defined by the WSDL 1.1 specification.

type WSDL struct {
	TargetNamespace string `xml:"targetNamespace,attr"`
	Types           struct {
		Schemas []*Schema `xml:"schema"`
	} `xml:"types"`
	Messages  []*Message  `xml:"message"`
	PortTypes []*PortType `xml:"portType"`
	Bindings  []*Binding  `xml:"binding"`
	Services  []*Service  `xml:"service"`
}

type Message struct {
	Name  string  `xml:"name,attr"`
	Parts []*Part `xml:"part"`
}

type Part struct {
	Name    string `xml:"name,attr"`
	Element string `xml:"element,attr"`
	Type    string `xml:"type,attr"`
}

type Operation struct {
	Name        string `xml:"name,attr"`
	Input       *MsgRef `xml:"input"`
	Output      *MsgRef `xml:"output"`
	InputName   string `xml:"input>message,attr"`
	OutputName  string `xml:"output>message,attr"`
}

type MsgRef struct {
	Message string `xml:"message,attr"`
}

type PortType struct {
	Name       string       `xml:"name,attr"`
	Operations []*Operation `xml:"operation"`
}

type SoapOperation struct {
	SoapAction string `xml:"soapAction,attr"`
}

type BindingOperation struct {
	Name          string         `xml:"name,attr"`
	SoapOperation *SoapOperation `xml:"operation"`
}

type Binding struct {
	Name       string             `xml:"name,attr"`
	Type       string             `xml:"type,attr"`
	Operations []*BindingOperation `xml:"operation"`
}

type Port struct {
	Name    string `xml:"name,attr"`
	Binding string `xml:"binding,attr"`
}

type Service struct {
	Name  string  `xml:"name,attr"`
	Ports []*Port `xml:"port"`
}
GOEOF
