	"anyType":            "AnyType",
	"anyURI":             "AnyURI",
	"NCName":             "NCName",
	"base64Binary":       "[]byte",
}

// opTypes maps XML Schema built-in type names to the Go type name used for
// SOAP operation request/response payloads.
var opTypes = map[string]string{
	"string": "string",
	"int":    "int",
	"byte":   "byte",
}

// xsdReceivers maps the Go date/time types to the receiver name used in the
// generated MarshalXML/UnmarshalXML methods.
var xsdReceivers = map[string]string{
	"soap.XSDDate":     "xd",
	"soap.XSDTime":     "xt",
	"soap.XSDDateTime": "xdt",
}

// resolveType resolves a type reference to its Go type. The second return
// value reports whether the type is a built-in one.
func resolveType(ref string) (string, bool) {
	local := localName(ref)
	if g, ok := xsdTypes[local]; ok {
		return g, true
	}
	if local == "" {
		return "interface{}", true
	}
	return camelize(local), false
}

// opType resolves the type reference of a message part.
func opType(ref string) string {
	local := localName(ref)
	if g, ok := opTypes[local]; ok {
		return g
	}
	return goName(local)
}
