	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// readSource reads the WSDL from a local file or downloads it from a URL.
func readSource(src string, insecure bool) ([]byte, string, error) {
	if strings.HasPrefix(src, "http://") || strings.HasPrefix(src, "https://") {
		fmt.Printf("🍀  Downloading file %s\n", src)
		client := &http.Client{}
		if insecure {
			client.Transport = &http.Transport{
				TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
			}
		}
		resp, err := client.Get(src)
		if err != nil {
			return nil, "", err
		}
		defer resp.Body.Close()
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, "", err
		}
		return data, src, nil
	}

	path, err := filepath.Abs(src)
	if err != nil {
		return nil, "", err
	}
	fmt.Printf("🍀  Reading file %s\n", path)
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, "", err
	}
	return data, path, nil
}

// fetch resolves the location of an imported schema relative to the location of
// the document that references it.
func fetchLocation(base, location string) string {
	if strings.HasPrefix(location, "http://") || strings.HasPrefix(location, "https://") {
		return location
	}
	if strings.HasPrefix(base, "http://") || strings.HasPrefix(base, "https://") {
		if i := strings.LastIndex(base, "/"); i >= 0 {
			return base[:i+1] + location
		}
		return location
	}
	dir := filepath.Dir(base)
	p := filepath.Join(dir, location)
	if abs, err := filepath.Abs(p); err == nil {
		return abs
	}
	return p
}

// loadDocument reads a document and all the schemas it imports.
func loadDocument(src string, insecure bool, loaded map[string]bool) ([]byte, []*Schema, error) {
	data, path, err := readSource(src, insecure)
	if err != nil {
		return nil, nil, err
	}
	loaded[path] = true

	var doc struct {
		Types struct {
			Schemas []*Schema `xml:"schema"`
		} `xml:"types"`
	}
	if err := xml.Unmarshal(data, &doc); err != nil {
		return nil, nil, err
	}

	var schemas []*Schema
	for _, s := range doc.Types.Schemas {
		schemas = append(schemas, s)
		for _, imp := range s.Imports {
			if imp.SchemaLocation == "" {
				continue
			}
			loc := fetchLocation(path, imp.SchemaLocation)
			if loaded[loc] {
				continue
			}
			fmt.Printf("🍀  Reading file %s\n", loc)
			_, sub, err := loadDocument(loc, insecure, loaded)
			if err != nil {
				return nil, nil, err
			}
			schemas = append(schemas, sub...)
		}
	}
	return data, schemas, nil
}
