{"command": "cd /workspace/src && cat > parse.go <<'GOEOF'
package main

import (
	"crypto/tls"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// readSource reads the WSDL from a local file or downloads it from a URL.
func readSource(src string, insecure bool) ([]byte, string, error) {
	if strings.HasPrefix(src, "http://") || strings.HasPrefix(src, "https://") {
		fmt.Printf("🍀  Downloading file %s\n", src)
		client := &http.Client{}
		if insecure {
			client.Transport = &http.Transport{
				TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
			}
		}
		resp, err := client.Get(src)
		if err != nil {
			return nil, "", err
		}
		defer resp.Body.Close()
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, "", err
		}
		return data, src, nil
	}

	path, err := filepath.Abs(src)
	if err != nil {
		return nil, "", err
	}
	fmt.Printf("🍀  Reading file %s\n", path)
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, "", err
	}
	return data, path, nil
}

// fetchLocation resolves the location of an imported schema relative to the
// location of the document that references it.
func fetchLocation(base, location string) string {
	if strings.HasPrefix(location, "http://") || strings.HasPrefix(location, "https://") {
		return location
	}
	if strings.HasPrefix(base, "http://") || strings.HasPrefix(base, "https://") {
		if i := strings.LastIndex(base, "/"); i >= 0 {
			return base[:i+1] + location
		}
		return location
	}
	p := filepath.Join(filepath.Dir(base), location)
	if abs, err := filepath.Abs(p); err == nil {
		return abs
	}
	return p
}

type wsdlDoc struct {
	Types struct {
		Schemas []*Schema `xml:"schema"`
	} `xml:"types"`
}

type xsdDoc struct {
	Schemas []*Schema `xml:"schema"`
}

func readDoc(src string, insecure bool, loaded map[string]bool) ([]byte, []*Schema, error) {
	data, path, err := readSource(src, insecure)
	if err != nil {
		return nil, nil, err
	}
	loaded[path] = true

	var doc xsdDoc
	if err := xml.Unmarshal(data, &doc); err != nil {
		return nil, nil, err
	}
	return data, doc.Schemas, nil
}

// loadSchemas reads the schemas of a document together with all the external
// schemas they import or include.
func loadSchemas(schemas []*Schema, base string, insecure bool, loaded map[string]bool) ([]*Schema, error) {
	var out []*Schema
	for _, s := range schemas {
