package main

// Builder that turns the parsed WSDL into the model used by the generators.

type builder struct {
	schemas    []*Schema
	makePublic bool
	xmlNames   map[string]map[string]bool
	schemaOf   map[string]*Schema
}

func newBuilder(schemas []*Schema, makePublic bool) *builder {
	b := &builder{
		schemas:    schemas,
		makePublic: makePublic,
		xmlNames:   make(map[string]map[string]bool),
		schemaOf:   make(map[string]*Schema),
	}
	for _, s := range schemas {
		for _, ct := range s.ComplexTypes {
			if _, ok := b.schemaOf[ct.Name]; !ok {
				b.schemaOf[ct.Name] = s
			}
		}
	}
	for _, s := range schemas {
		for _, el := range s.Elements {
			b.walkElement(el)
		}
		for _, ct := range s.ComplexTypes {
			b.walkComplexType(ct)
		}
	}
	return b
}

func (b *builder) walkElement(el *Element) {
	if el == nil {
		return
	}
	if el.Type != "" {
		b.addRef(localName(el.Type), el.Name)
	}
	if el.ComplexType != nil {
		b.walkComplexType(el.ComplexType)
	}
}

func (b *builder) walkComplexType(ct *ComplexType) {
	if ct == nil {
		return
	}
	for _, el := range ctFields(ct) {
		b.walkElement(el)
	}
}

func (b *builder) addRef(typeName, elName string) {
	if typeName == "" {
		return
	}
	m, ok := b.xmlNames[typeName]
	if !ok {
		m = make(map[string]bool)
		b.xmlNames[typeName] = m
	}
	m[elName] = true
}

// xmlName returns the XMLName value for a named complex type, if it can be
// determined unambiguously.
func (b *builder) xmlName(typeName string) (string, string) {
	names := b.xmlNames[typeName]
	if len(names) != 1 {
		return "", ""
	}
	var name string
	for n := range names {
		name = n
	}
	if name == typeName {
		return "", ""
	}
	s := b.schemaOf[typeName]
	ns := ""
	if s != nil {
		ns = s.TargetNamespace
	}
	return ns + " " + name, name
}

func ctFields(ct *ComplexType) []*Element {
	var out []*Element
	if ct.Sequence != nil {
		out = append(out, ct.Sequence.Elements...)
	}
	if ct.Choice != nil {
		out = append(out, ct.Choice.Elements...)
	}
	if ct.All != nil {
		out = append(out, ct.All.Elements...)
	}
	return out
}

func ctAnys(ct *ComplexType) []*Any {
	if ct.Sequence == nil {
		return nil
	}
	return ct.Sequence.Anys
}

func ctChoices(ct *ComplexType) []*Choice {
	if ct.Sequence == nil {
		return nil
	}
	return ct.Sequence.Choices
}
GOEOF
echo ok"}

