package main

// Field and type construction.

// fieldOf builds the Go field declaration for an XML schema element.
func (b *builder) fieldOf(el *Element, ns string, anon bool) *FieldDecl {
	f := &FieldDecl{}
	f.Comment = comment(el.Doc)

	name := el.Name
	branch := ""
	switch {
	case el.Type != "":
		branch = "ref"
	case el.SimpleType != nil:
		branch = "loc"
	case el.Ref != "":
		branch = "ref"
		name = localName(el.Ref)
	default:
		branch = "anon"
	}

	switch branch {
	case "ref":
		f.Name = fieldName(name)
