package main

// Field and type construction.

// fieldOf builds the Go field declaration for an XML schema element.
func (b *builder) fieldOf(el *Element, anon bool) *FieldDecl {
	f := &FieldDecl{}
	f.Comment = comment(el.Doc)

	name := el.Name
	ref := el.Type
	switch {
	case el.Type != "":
	case el.SimpleType != nil:
		ref = ""
	case el.Ref != "":
		ref = el.Ref
		name = localName(el.Ref)
	}

	switch {
	case ref != "":
		f.Name = fieldName(name)
		gotype, builtin := resolveType(ref)
		f.GoType = pointer(gotype, !builtin || el.Nillable)
		if el.MaxOccurs == "unbounded" {
			f.GoType = "[]" + f.GoType
		}
	case el.SimpleType != nil:
		f.Name = elemName(name)
		st := el.SimpleType
		base := ""
		list := false
		if st.Restriction != nil {
			base = st.Restriction.Base
		} else if st.List != nil {
			base = st.List.ItemType
			list = true
		}
		gotype, builtin := resolveType(base)
		if list && base != "" {
			f.GoType = "[]" + gotype
		} else {
			f.GoType = pointer(gotype, !builtin)
		}
	default:
		f.Name = checkName(camelize(name))
		f.GoType = "struct"
		if el.MaxOccurs == "unbounded" {
			f.GoType = "[]struct"
		}
		f.Anon = b.structOf(el.ComplexType, true)
	}

	if name == "" {
		f.XML = ",omitempty"
	} else {
		f.XML = name + ",omitempty"
	}
	f.JSON = f.Name + ",omitempty"
	return f
}

// attrOf builds the Go field declaration for an XML schema attribute.
func (b *builder) attrOf(at *Attribute, ns string) *FieldDecl {
	f := &FieldDecl{}
	f.Comment = comment(at.Doc)
	name := at.Name
	if name == "" && at.Ref != "" {
		name = localName(at.Ref)
	}
	f.Name = elemName(name)
	gotype, builtin := "", false
	switch {
	case at.Type != "":
		gotype, builtin = resolveType(at.Type)
	case at.SimpleType != nil:
		base := ""
		if at.SimpleType.Restriction != nil {
			base = at.SimpleType.Restriction.Base
		} else if at.SimpleType.List != nil {
			base = at.SimpleType.List.ItemType
		}
		gotype, builtin = resolveType(base)
	default:
		gotype, builtin = "interface{}", true
	}
	f.GoType = pointer(gotype, !builtin || at.Nillable)
	f.XML = ns + " " + name + ",attr,omitempty"
	f.JSON = f.Name + ",omitempty"
	return f
}

func pointer(gotype string, ptr bool) string {
	if ptr {
		return "*" + gotype
	}
	return gotype
}

// structOf builds the Go struct declaration for a complex type.
func (b *builder) structOf(ct *ComplexType, anon bool) *StructDecl {
	s := &StructDecl{}
	if ct == nil {
		return s
	}
	if ct.SimpleContent != nil {
		if ct.SimpleContent.Extension != nil {
			gotype, builtin := resolveType(ct.SimpleContent.Extension.Base)
			s.Fields = append(s.Fields, &FieldDecl{
				Name:   "Value",
				GoType: pointer(gotype, !builtin),
				XML:    ",chardata",
				JSON:   "-,",
			})
			for _, at := range ct.SimpleContent.Extension.Attributes {
				s.Fields = append(s.Fields, b.attrOf(at, anonNS))
			}
		}
		return s
	}

	for _, el := range ctFields(ct) {
		s.Fields = append(s.Fields, b.fieldOf(el, anon))
	}
	if !anon {
		for range ctAnys(ct) {
			s.Fields = append(s.Fields, &FieldDecl{
				Name:   "Items",
				GoType: "[]string",
				XML:    ",any",
				JSON:   "items,omitempty",
			})
		}
	}
	if ct.Choice != nil {
		for _, el := range ct.Choice.Elements {
			s.Fields = append(s.Fields, b.fieldOf(el, anon))
		}
	}
	for _, c := range ctChoices(ct) {
		for _, el := range c.Elements {
			s.Fields = append(s.Fields, b.fieldOf(el, anon))
		}
	}
	if ct.All != nil {
		for _, el := range ct.All.Elements {
			s.Fields = append(s.Fields, b.fieldOf(el, anon))
		}
	}
	for _, at := range ct.Attributes {
		s.Fields = append(s.Fields, b.attrOf(at, anonNS))
	}
	return s
}
