package main

import "strings"

// simpleTypeOf returns the Go type of a simple type declaration.
func simpleTypeOf(st *SimpleType) string {
	if st == nil {
		return "interface{}"
	}
	if st.Union != nil {
		return "string"
	}
	if st.List != nil {
		if st.List.ItemType == "" {
			return "interface{}"
		}
		gotype, _ := resolveType(st.List.ItemType)
		return "[]" + gotype
	}
	if st.Restriction != nil {
		gotype, _ := resolveType(st.Restriction.Base)
		return gotype
	}
	return "interface{}"
}

func (b *builder) simpleTypeDecl(st *SimpleType) *TypeDecl {
	d := &TypeDecl{
		Comment: comment(st.Doc),
		Name:    typeName(st.Name),
		GoType:  simpleTypeOf(st),
	}
	if st.Restriction != nil {
		for _, e := range st.Restriction.Enums {
			d.Enums = append(d.Enums, &EnumDecl{
				Comment: comment(e.Doc),
				Name:    typeName(st.Name) + goName(e.Value),
				Value:   e.Value,
			})
		}
	}
	return d
}

func (b *builder) elementDecl(el *Element, ns string) *TypeDecl {
	name := typeName(el.Name)
	switch {
	case el.Type != "":
		gotype, _ := resolveType(el.Type)
		if gotype == name {
			return nil
		}
		return &TypeDecl{Name: name, GoType: gotype, Methods: gotype}
	case el.ComplexType != nil:
		s := b.structOf(el.ComplexType, ns, false)
		s.XMLName = ns + " " + el.Name
		return &TypeDecl{Name: name, Struct: s}
	case el.SimpleType != nil:
		d := &TypeDecl{Name: name, GoType: simpleTypeOf(el.SimpleType)}
		if el.SimpleType.Restriction != nil {
			for _, e := range el.SimpleType.Restriction.Enums {
				d.Enums = append(d.Enums, &EnumDecl{
					Comment: comment(e.Doc),
					Name:    name + goName(e.Value),
					Value:   e.Value,
				})
			}
		}
		return d
	}
	return nil
}

func (b *builder) complexTypeDecl(ct *ComplexType, ns string) *TypeDecl {
