	s.XMLName, _ = b.xmlName(ct.Name)
	return &TypeDecl{Name: typeName(ct.Name), Struct: s}
}

func (b *builder) findElement(name string) *Element {
	for _, s := range b.schemas {
		for _, el := range s.Elements {
			if el.Name == name {
				return el
			}
		}
	}
	return nil
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicodeToLower(r[0])
	return string(r)
}

func (b *builder) model(wsdl *WSDL, pkg string) *Model {
	m := &Model{Package: pkg}

	for _, s := range b.schemas {
		ns := s.TargetNamespace
		for _, st := range s.SimpleTypes {
			m.Types = append(m.Types, b.simpleTypeDecl(st))
		}
		for _, el := range s.Elements {
			if d := b.elementDecl(el, ns); d != nil {
				m.Types = append(m.Types, d)
			}
		}
		for _, ct := range s.ComplexTypes {
			m.Types = append(m.Types, b.complexTypeDecl(ct, ns))
		}
	}

	msgs := make(map[string]*Message)
	for _, msg := range wsdl.Messages {
		msgs[msg.Name] = msg
	}
