			req := b.partType(op.Input, op.InputName)
			res := b.partType(op.Output, op.OutputName)
			svc.Ops = append(svc.Ops, &OperationDecl{
				Comment:  blockComment(op.Doc),
				Name:     name + goName(op.Name),
				Request:  req,
				Response: res,
				Action:   b.action(wsdl, pt.Name, op.Name),
			})
			m.Server = append(m.Server, &ServerOp{
				Name:     req,
				Request:  req,
				Response: res,
			})
		}
		m.Services = append(m.Services, svc)
	}
	return m
}

func (b *builder) partType(ref *MsgRef, name string) string {
	var msgName string
	if ref != nil && ref.Message != "" {
		msgName = localName(ref.Message)
	} else if name != "" {
		msgName = localName(name)
	}
	if msgName == "" {
		return goName("")
	}
	msg := b.msgs[msgName]
	if msg == nil || len(msg.Parts) == 0 {
		return goName("")
	}
	p := msg.Parts[0]
	if p.Type != "" {
		return opType(p.Type)
	}
	if p.Element != "" {
		el := b.findElement(localName(p.Element))
		if el == nil {
			return goName("")
		}
		if el.Type != "" {
			return opType(el.Type)
		}
		return goName(el.Name)
	}
	return goName("")
}

func (b *builder) action(wsdl *WSDL, portType, op string) string {
	for _, bd := range wsdl.Bindings {
		if localName(bd.Type) != portType {
			continue
		}
		for _, bo := range bd.Operations {
			if bo.Name == op {
				if bo.SoapOperation != nil && bo.SoapOperation.SoapAction != "" {
					return bo.SoapOperation.SoapAction
				}
				return "''"
			}
		}
	}
	return "''"
}

func blockComment(s string) string {
	if strings.TrimSpace(s) == "" {
		return ""
	}
	return "/* " + s + " */"
}
GOEOF
