package main

import (
	"fmt"
	"strings"
)

// generateClient produces the Go source of the client code.
func generateClient(m *Model) string {
	var b strings.Builder

	b.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	b.WriteString(fmt.Sprintf("package %s\n\n", m.Package))
	b.WriteString("import (\n")
