cat > main.go <<'GOEOF'
package main

import (
	"encoding/xml"
	"fmt"
	"os"
	"path/filepath"
)

const version = "v0.5.0"

func usage() {
	fmt.Fprintf(os.Stderr, "Usage: %s [options] myservice.wsdl\n", os.Args[0])
	flag.PrintDefaults()
}

func main() {
	var (
		dir         string
		insecure    bool
		makePublic  bool
		out         string
		pkg         string
		showVersion bool
	)
	flag.BoolVar(&insecure, "i", false, "Skips TLS Verification")
	flag.StringVar(&out, "o", "myservice.go", "File where the generated code will be saved")
	flag.StringVar(&pkg, "p", "myservice", "Package under which code will be generated")
	flag.StringVar(&dir, "d", "./", "Directory under which package directory will be created")
	flag.BoolVar(&makePublic, "make-public", true, "Make the generated types public/exported")
	flag.BoolVar(&showVersion, "v", false, "Shows gowsdl version")
	flag.Usage = usage
	flag.Parse()

	if showVersion {
		fmt.Printf("🍀  %s\n", version)
		return
	}

	if flag.NArg() < 1 {
		flag.Usage()
		return
	}
	src := flag.Arg(0)

	setPublic(makePublic)

	data, path, err := readSource(src, insecure)
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	var w WSDL
	if err := xml.Unmarshal(data, &w); err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	schemas, err := loadSchemas(w.Types.Schemas, path, insecure, map[string]bool{path: true})
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}
	schemas = append(w.Types.Schemas, schemas...)

	b := newBuilder(schemas, makePublic)
	m := b.model(&w, pkg)

	client, err := formatSource(generateClient(m))
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
	}
	server, err := formatSource(generateServer(m))
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
	}

	outDir := filepath.Join(dir, pkg)
	if err := os.MkdirAll(outDir, 0755); err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}
	if err := os.WriteFile(filepath.Join(outDir, out), []byte(client), 0644); err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}
	if err := os.WriteFile(filepath.Join(outDir, "server"+out), []byte(server), 0644); err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("🍀  Done 👍\n")
}
GOEOF
