package main

import (
	"fmt"
	"strings"
)

// generateServer produces the Go source of the server code.
func generateServer(m *Model) string {
	var b strings.Builder

	b.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	b.WriteString(fmt.Sprintf("package %s\n\n", m.Package))
	b.WriteString("import (\n")
	b.WriteString("\t\"encoding/xml\"\n")
	b.WriteString("\t\"errors\"\n")
	b.WriteString("\t\"fmt\"\n")
	b.WriteString("\t\"net/http\"\n")
	b.WriteString("\t\"reflect\"\n")
	b.WriteString("\t\"strings\"\n")
	b.WriteString(")\n\n")
	b.WriteString(fmt.Sprintf("var wsdl = `%s`\n\n", m.WSDL))
	b.WriteString("var WSDLUndefinedError = errors.New(\"Server was unable to process request. --> Object reference not set to an instance of an object.\")\n\n")

	b.WriteString("type SOAPEnvelopeRequest struct {\n")
	b.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Envelope\"`\n")
	b.WriteString("\tBody    SOAPBodyRequest\n}\n\n")

	b.WriteString("type SOAPBodyRequest struct {\n")
	b.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n")
	if len(m.Server) > 0 {
		b.WriteString("\n")
	}
	for _, op := range m.Server {
		b.WriteString(fmt.Sprintf("\t%s *%s `xml:,omitempty`\n\n", op.Name, op.Request))
	}
	b.WriteString("}\n\n")

	b.WriteString("type SOAPEnvelopeResponse struct {\n")
	b.WriteString("\tXMLName    xml.Name `xml:\"soap:Envelope\"`\n")
	b.WriteString("\tPrefixSoap string   `xml:\"xmlns:soap,attr\"`\n")
	b.WriteString("\tPrefixXsi  string   `xml:\"xmlns:xsi,attr\"`\n")
	b.WriteString("\tPrefixXsd  string   `xml:\"xmlns:xsd,attr\"`\n\n")
	b.WriteString("\tBody SOAPBodyResponse\n}\n\n")
	b.WriteString("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n")
	b.WriteString("\treturn &SOAPEnvelopeResponse{\n")
	b.WriteString("\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n")
	b.WriteString("\t\tPrefixXsd:  \"http://www.w3.org/2001/XMLSchema\",\n")
	b.WriteString("\t\tPrefixXsi:  \"http://www.w3.org/2001/XMLSchema-instance\",\n")
	b.WriteString("\t}\n}\n\n")

	b.WriteString("type Fault struct {\n")
	b.WriteString("\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n")
	b.WriteString("\tSpace   string   `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n")
	b.WriteString("\tCode   string `xml:\"faultcode,omitempty\"`\n")
	b.WriteString("\tString string `xml:\"faultstring,omitempty\"`\n")
	b.WriteString("\tActor  string `xml:\"faultactor,omitempty\"`\n")
	b.WriteString("\tDetail string `xml:\"detail,omitempty\"`\n}\n\n")

	b.WriteString("type SOAPBodyResponse struct {\n")
	b.WriteString("\tXMLName xml.Name `xml:\"soap:Body\"`\n")
	b.WriteString("\tFault   *Fault   `xml:\",omitempty\"`\n")
	if len(m.Server) > 0 {
		b.WriteString("\n")
	}
	for _, op := range m.Server {
		b.WriteString(fmt.Sprintf("\t%s *%s `xml:,omitempty`\n\n", op.Name, op.Response))
	}
	b.WriteString("}\n\n")

	for _, op := range m.Server {
		b.WriteString(fmt.Sprintf("func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n", op.Name, op.Request, op.Response))
		b.WriteString("\treturn nil, WSDLUndefinedError\n}\n\n")
	}

	b.WriteString(serverCall())
	b.WriteString("\nfunc Endpoint(w http.ResponseWriter, r *http.Request) {\n")
	b.WriteString("\trequest := SOAPEnvelopeRequest{}\n")
	b.WriteString("\trequest.call(w, r)\n}\n")
	return b.String()
}

func serverCall() string {
	return `func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {
	w.Header().Add("Content-Type", "text/xml; charset=utf-8")
	val := reflect.ValueOf(&service.Body).Elem()
	n := val.NumField()
	var field reflect.Value
	var name string
	find := false

	if r.Method == http.MethodGet {
		w.Write([]byte(wsdl))
		return
	}

	resp := NewSOAPEnvelopResponse()
	defer func() {
		if r := recover(); r != nil {
			resp.Body.Fault = &Fault{}
			resp.Body.Fault.Space = "http://schemas.xmlsoap.org/soap/envelope/"
			resp.Body.Fault.Code = "soap:Server"
			resp.Body.Fault.Detail = fmt.Sprintf("%v", r)
			resp.Body.Fault.String = fmt.Sprintf("%v", r)
		}
		xml.NewEncoder(w).Encode(resp)
	}()

	header := r.Header.Get("Content-Type")
	if strings.Index(header, "application/soap+xml") >= 0 {
		panic("Could not find an appropriate Transport Binding to invoke.")
	}

	err := xml.NewDecoder(r.Body).Decode(service)
	if err != nil {
		panic(err)
	}

	for i := 0; i < n; i++ {
		field = val.Field(i)
		name = val.Type().Field(i).Name
		if field.Kind() != reflect.Ptr {
			continue
		}
		if field.IsNil() {
			continue
		}
		if field.IsValid() {
			find = true
			break
		}
	}

	if !find {
		panic(WSDLUndefinedError)
	} else {
		m := val.Addr().MethodByName(name + "Func")
		if !m.IsValid() {
			panic(WSDLUndefinedError)
		}

		vals := m.Call([]reflect.Value{field})
		if vals[1].IsNil() {
			reflect.ValueOf(&resp.Body).Elem().FieldByName(name).Set(vals[0])
		} else {
			panic(vals[1].Interface())
		}
	}

}
`
}
