func elemName(s string) string {
	return goName(s)
}

// localName strips the namespace prefix of a qualified name.
func localName(s string) string {
	parts := strings.Split(s, ":")
	if len(parts) == 2 {
		return parts[1]
	}
	return parts[0]
}

func comment(s string) string {
	if strings.TrimSpace(s) == "" {
